		},
	},
	mentions = {
		{ text = "«Миражи»" },
		{ text = "«Сбор лома»" },
		{ text = "«Чары пылающего огня»" },
	},
	bonds = {
		{ id = "prospector-ryedol", name = "геолог Райдол", note = "делит с ним лагерь" },
		{ id = "garek", name = "Гарек", note = "слышал о его помощниках" },
	},
})

Translate("ruRU", "garek", {
	title = "Гарек",
	subtitle = "Посланец Кирин-Тора",
	found = "Лощина Суховея, к западу от Долины Летлор",
	hint = "Найдите молчаливого мага, который стережет Долину Летлор.",
	allegiance = "Кирин-Тор",
	sections = {
		{
			title = "Обзор",
			text = [=[{link:garek-bandarion}Гарек{/link} — маг, которого послал в {link:badlands}Бесплодные земли{/link} наставник из {link:kirin-tor}Кирин-Тора{/link}, Крас. Маг держит одинокий лагерь возле Долины {link:lethlor-ravine}Летлор{/link} и мало говорит о своем поручении — лишь то, что оно весьма важно и что касается оно беды, которая зреет в долине.]=],
		},
		{
			title = "Значение",
			text = [=[{link:garek-bandarion}Гарек{/link} показывает, что {link:kirin-tor}Кирин-Тор{/link} по-прежнему следит за черными драконами, даже в эти смутные годы. Под Долиной {link:lethlor-ravine}Летлор{/link} лежат два помощника {link:deathwing}Смертокрыла{/link}, и его наставник решил, что нельзя допустить ни малейшего риска их освобождения.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он ищет Знак Земли — ключ от темницы драконов, украденный шайкой бродячих {link:ogres}огр{/link}ов.
• Он узнал историю темницы и ее создателей, {link:dwarves}дворф{/link}ов Черного Железа.
• Он решил, что {link:blacklash}Чернохлыст{/link} и {link:hematus}Гематус{/link} не должны проснуться вновь.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[{link:garek-bandarion}Гарек{/link} не говорит, кем он был до того, как поступил на службу к наставнику, и ни одна запись этого не открывает.]=],
		},
	},
	chapters = {
		{
			title = "Знак Земли",
			hint = "Верните украденный ключ магу Кирин-Тора.",
			text = [=[Знак Земли сделали {link:dwarves}дворф{/link}ы Черного Железа из Крепости Ангор, чтобы сковать двух помощников {link:deathwing}Смертокрыл{/link}а — драконов-близнецов {link:blacklash}Чернохлыст{/link}а и {link:hematus}Гематус{/link}а. Когда ключ принесли, {link:garek-bandarion}Гарек{/link} заговорил свободнее. Черные драконы стали гнездиться в долине. {link:ogres}Огры{/link} сумели украсть ключ. Темнице больше нельзя было доверять.]=],
		},
		{
			title = "Вечные сны",
			hint = "Покончите с угрозой, исходящей от драконов Летлора.",
			text = [=[С ключом можно было вынуть три рунных камня из их столпов и вставить в Печать Земли. Печать сломалась, и драконы оказались на свободе ровно на то время, какое понадобилось, чтобы их убить. {link:garek-bandarion}Гарек{/link} просил лишь об одном: сделать их сны вечными. Когда это было сделано, он стал готовиться к возвращению к своему наставнику с вестью, что {link:kirin-tor}Кирин-Тор{/link}у больше незачем бояться узников {link:lethlor-ravine}Летлор{/link}а.]=],
		},
	},
	mentions = {
		{ text = "«Дрожь земли», ключ возвращен" },
		{ text = "«Дрожь земли», драконы убиты" },
		{ text = "«Печать земли»" },
	},
	bonds = {
		{ id = "sigrun-ironhew", name = "Сигрун Железоруб", note = "рассказал ему о тех, кто помогает" },
		{ id = "blacklash", name = "Чернохлыст", note = "узник Летлора" },
		{ id = "hematus", name = "Гематус", note = "узник Летлора" },
		{ id = "boss-tho-grun", name = "главарь То'грун", note = "украл ключ" },
	},
})

