})

Translate("ruRU", "hematus", {
	title = "Гематус",
	subtitle = "Помощник Смертокрыла",
	found = "Скован под Печатью Земли, Долина Летлор",
	hint = [=[Сразитесь со вторым драконом, который просыпается, когда сломана Печать Земли.]=],
	allegiance = "Черные драконы",
	sections = {
		{
			title = "Обзор",
			text = [=[Гематус — близнец дракона {link:blacklash}Чернохлыст{/link}а и, как и тот, помощник {link:deathwing}Смертокрыла{/link}. {link:dark-iron-dwarves}Дворфы Черного Железа{/link} из Крепости Ангор заковали его в цепи под Долиной {link:lethlor-ravine}Летлор{/link} и запечатали темницу тремя рунными камнями. Он просыпается в цепях, когда печать сломана, и просыпается в гневе.]=],
		},
		{
			title = "Значение",
			text = [=[Пока Гематус и его близнец были живы, у черных драконов было два старых полководца, ждавших под Бесплодными землями. Черные драконы, которые теперь гнездятся в долине, возможно, пришли за ними.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он служил {link:deathwing}Смертокрыл{/link}у как один из его помощников.
• {link:dark-iron-dwarves}Дворфы Черного Железа{/link} сковали его цепями, которые носят его имя.]=],
		},
	},
	mentions = {
		{ text = "«Дрожь земли»" },
		{ text = "«Расторгнутые союзы»" },
	},
	bonds = {
		{ id = "blacklash", name = "Чернохлыст", note = "его близнец" },
		{ id = "garek", name = "Гарек", note = "добивается его смерти" },
	},
})

Translate("ruRU", "lotwil-veriatus", {
	title = "Лотвил Вериатус",
	subtitle = "Маг и механик из Караноса",
	found = "Его лагерь в Знойных Песках",
	hint = [=[Найдите гнома-мага, который испытывает свои изобретения в Знойных Песках.]=],
	allegiance = "Гномы · Каранос",
	aliases = { "Лотвил" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лотвил Вериатус — {link:gnomes}гном{/link}, который соединяет алхимию, инженерное дело и тайную магию на службе собственному любопытству. Он пришел из {link:kharanos}Каранос{/link}а в {link:badlands}Бесплодные земли{/link}, чтобы создать свой величайший труд: оковы подчинения стихий, которые позволят магу повелевать элементалями гораздо сильнее всех, каких вызывали прежде. Его помощник {link:lucien-tosselwrench}Люсьен{/link} и его неуклюжий механический слуга Серво делят с ним лагерь. Лотвил блестяще умен, рассеян и бодро убежден, что всякая неудача — малая.]=],
		},
		{
			title = "Значение",
			text = [=[Лотвил — ученый с настоящей славой в науках о стихиях, и даже {link:horde}Орда{/link} {link:kargath}Каргат{/link}а ищет его суждения. Есть у него и прошлое. Давным-давно он сражался с {link:dwarves}дворф{/link}ом Черного Железа, который обратил труд его жизни в оружие, и считал этого врага мертвым.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он изучает элементалей камня Бесплодных земель, чтобы создать свои оковы.
• Он охлаждает и укрепляет оковы ледяным маслом и устройством, которое называется гирохронатом.
• Готовыми оковами он вызывает каменного стража, и это идет не так, как он задумал.
• Он знает метки создателя големов Аргелмаха.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Летописи не говорят, как Лотвил и Аргелмах встретились впервые и как {link:dwarves}дворф{/link} Черного Железа завладел трудом {link:gnomes}гном{/link}а.]=],
		},
	},
	chapters = {
		{
			title = "Изучение стихий",
			hint = [=[Соберите то, что нужно гному, с элементалей камня Бесплодных земель.]=],
			text = [=[Осколки с меньших элементалей, плиты с больших и наконец наручи каменных уз с величайших из них. Каждая вещь позволяла {link:gnomes}гном{/link}у испытать его заклинания на веществе живого камня. Каждое испытание шло так, как он предсказывал. Он начал говорить об элементалях, которыми скоро будет повелевать, и о том, как они посрамят все прежние призывы.]=],
		},
		{
			title = "Это будет трудно",
			hint = [=[Помогите гному закончить оковы и разберитесь с тем, что последует.]=],
			text = [=[Оковы были готовы. Лотвил призвал помощника и механического слугу в свидетели и вызвал стража стихийного камня. Тот не подчинился. Когда тварь одолели, а оковы вернули, Лотвил признал, что ждал иного исхода. Он не мог сказать, что пошло не так. Он рад, сказал он, что его магия оказалась под рукой и отправила тварь домой.]=],
		},
		{
			title = "Восстание машин",
			hint = [=[Отнесите меченый осколок элементаля из Каргата в лагерь гнома.]=],
			text = [=[Осколки были взяты с големов в {link:burning-steppes}Пылающих степях{/link}, и на них стояли инициалы. Когда Лотвил их увидел, его лицо побелело. Он знал эти метки. Они принадлежали {link:dwarves}дворф{/link}у Черного Железа Аргелмаху, который обратил собственный труд {link:gnomes}гном{/link}а во зло и которого Лотвил убил своей рукой много лет назад. Когда голову этого дворфа вынесли из {red:blackrock-depths}Глубин Черной горы{/red}, она оказалась не из плоти. Это была машина, сделанная по его образу, и Лотвил боялся, что на ее место поднимется другая.]=],
		},
	},
	mentions = {
		{ text = "«Изучение стихий: камень»" },
		{ text = "«Изучение стихий: камень»" },
		{ text = "«Изучение стихий: камень»" },
		{ text = "«Побеждают холодные головы»" },
		{ text = "«Гиро... что?»" },
		{ text = "«Это будет трудно»" },
		{ text = "«Это будет трудно», шестеренка доставлена" },
		{ text = "«Это будет трудно», страж выпущен" },
		{
			text = [=[«Восстание машин», осколок принесен из {link:kargath}Каргат{/link}а]=],
		},
		{
			text = [=[«Восстание машин», голова {link:dwarves}дворф{/link}а Аргелмаха]=],
		},
	},
	bonds = {
		{ id = "lucien-tosselwrench", name = "Люсьен Тоссельренч", note = "его помощник" },
		{ id = "hierophant-theodora-mulvadania", name = "иерофант Теодора Мулвадания", note = "ищет его суждения" },
		{ id = "golem-lord-argelmach", name = "повелитель големов Аргелмах", note = "его старый враг" },
	},
})

Translate("ruRU", "lucien-tosselwrench", {
	title = "Люсьен Тоссельренч",
	subtitle = "Помощник гнома Лотвила Вериатуса",
	found = "Лагерь гнома-мага в Знойных Песках",
	hint = [=[Поговорите с помощником, который держится на опасливом расстоянии от трудов своего наставника.]=],
	allegiance = "Каранос",
	aliases = { "Люсьен" },
	sections = {
		{
			title = "Обзор",
			text = [=[Люсьен Тоссельренч — помощник {link:gnomes}гном{/link}а {link:lotwil-veriatus}Лотвил{/link}а Вериатуса, и он научился у наставника большему, чем тот знает. Из изысканий наставника в Бесплодных землях он вывел собственный рецепт зелья, и он зачаровывает наручи лишним камнем, который собирает Лотвил. Он также знает наставника достаточно хорошо, чтобы прятаться в укрытие перед каждым опытом.]=],
		},
		{
			title = "Значение",
			text = [=[Люсьен — практичная половина лагеря. Там, где {link:lotwil-veriatus}Лотвил{/link} видит впереди торжество, Люсьен видит беду и готовится к ней.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он запасает зелья исцеления и невидимости на случай, если труд наставника пойдет не так.
• Он делает зачарованные наручи из остатков камня элементалей.
• Он вручает шестеренку номер пять, а потом отступает в укрытие.]=],
		},
	},
	mentions = {
		{ text = "«Жидкий камень»" },
		{ text = "«Камень лучше ткани»" },
		{ text = "«Это будет трудно»" },
		{ text = "«Это будет трудно»" },
	},
	bonds = {
		{ id = "lotwil-veriatus", name = "Лотвил Вериатус", note = "его наставник" },
	},
})

Translate("ruRU", "rigglefuzz", {
	title = "Ригглфузз",
	subtitle = "Гоблин-повар Бесплодных земель",
	found = "Лагерь в Долине Клыков",
	hint = [=[Найдите гоблина, который жарит крылья канюков посреди Бесплодных земель.]=],
	allegiance = "Гоблины",
	sections = {
		{
			title = "Обзор",
			text = [=[Ригглфузз — гоблин, который живет в сердце Бесплодных земель и выживает там благодаря хитрости. Он отгоняет зверей световыми бомбами и гордится своими крыльями канюка на углях, чей запах, по его словам, приманивает голодных за многие мили. Есть у него и обида. Когда-то клан Тенегорн утащил его в {link:angor-fortress}Крепость Ангор{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Ригглфузз — тот, кто открыл клану Тенегорн тайну странных камней {link:uldaman}Ульдаман{/link}а. Его увели в {link:angor-fortress}Крепость Ангор{/link} изучать два вида камня из хранилища, и он обнаружил, что при верной обработке они дают ровную и долгую силу. Когда он рассказал об этом, его вышвырнули и принялись копать еще.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он делает световые бомбы из толченого голубого жемчуга, который привозят с рифов {link:stranglethorn-vale}Тернистой долины{/link}.
• Он жарит крылья канюков и делится рецептом с теми, кто ему помогает.
• Он хочет получить камни силы {link:uldaman}Ульдаман{/link}а для собственных устройств.]=],
		},
	},
	mentions = {
		{ text = "«Крылья канюка на углях»" },
		{ text = "«Ныряние за жемчугом»" },
		{ text = "«Рецепт световой бомбы»" },
		{ text = "«Камни силы»" },
	},
	bonds = {
		{ id = "martek-the-exiled", name = "Мартек Изгнанник", note = "делит с ним лагерь" },
	},
})

Translate("ruRU", "martek-the-exiled", {
	title = "Мартек Изгнанник",
	subtitle = "Кузнец-изгнанник",
	found = "Лагерь в Долине Клыков",
	hint = [=[Найдите кузнеца, который пришел в Бесплодные земли, чтобы его оставили в покое.]=],
	allegiance = "Нет",
	aliases = { "Мартек" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мартек — кузнец большого мастерства, который знает о металле больше, чем почти кто-либо. За ним к тому же охотятся. Многие хотели бы видеть его мертвым, и в каждом чужаке он ждет одного из них. Он спрашивает гостей, пришли ли они из-за секиры, которую он сделал для {link:ogres}огр{/link}а {link:gath-ilzogg}Гат'Илзогга{/link}, или отомстить за честь некой {link:duke-nicholas-zverenhoff}герцог{/link}ини Памей, и говорит, что ему все равно.]=],
		},
		{
			title = "Значение",
			text = [=[Мартек нашел в Бесплодных землях индурий — металл, который сопротивляется жару и нагрузке лучше любого другого. Настоящая руда лежит глубоко в {link:uldaman}Ульдаман{/link}е. Через него весть о ней дошла до {link:gnomes}гном{/link}а {link:fizzle-brassbolts}Физзла Медноштифа{/link} в {link:thousand-needles}Тысяче Игл{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он выковал секиру для {link:ogres}огр{/link}а {link:gath-ilzogg}Гат'Илзогг{/link}а.
• Он испытывает чешуйки индурия, которые носят {link:troggs}трогг{/link}и Каменного Свода.
• Он передает {link:gnomes}гном{/link}у Физзлу Медноштифу весть, что из индурия можно сделать поршни для его гоночной машины.]=],
		},
	},
	mentions = {
		{ text = "«Мартек Изгнанник»" },
		{ text = "«Индурий»" },
		{ text = "«Вести для {link:gnomes}гном{/link}а Физзла»" },
	},
	bonds = {
		{ id = "fizzle-brassbolts", name = "Физзл Медноштиф", note = "один из немногих, кто желает ему добра" },
		{ id = "rigglefuzz", name = "Ригглфузз", note = "делит с ним лагерь" },
		{ id = "gath-ilzogg", name = "Гат'Илзогг", note = "купил его секиру" },
	},
})

Translate("ruRU", "warlord-goretooth", {
	title = "Полководец Кровавый Клык",
	subtitle = "Командующий Экспедиционным корпусом Каргата",
	found = "Каргат",
	hint = [=[Поговорите с полководцем, который командует войском Орды в Каргате.]=],
	allegiance = "Орда · Экспедиционный корпус Каргата",
	aliases = { "Кровавый Клык" },
	sections = {
		{
			title = "Обзор",
			text = [=[Полководец Кровавый Клык командует Экспедиционным корпусом {link:kargath}Каргат{/link}а — войском, которое {link:horde}Орда{/link} держит в Бесплодных землях, чтобы сражаться с {link:blackrock-clan}кланом Черной горы{/link} и {link:dwarves}дворф{/link}ами Черного Железа {link:blackrock-mountain}Черной горы{/link}. Он суровый солдат, слишком занятой для посетителей и слишком гордый, чтобы показывать страх. Он говорит приказами. Его объявления о розыске висят по всему Каргату, и каждое обещает награду тому, кто исполнит приговор.]=],
		},
		{
			title = "Значение",
			text = [=[Кровавый Клык ведет самый долгий поход Орды в Восточных королевствах. Его войско тяжело пострадало: генерал {link:dwarves}дворф{/link}ов Черного Железа Кузня Гнева вырезал его 109-ю дивизию. Кровавый Клык поклялся, что Кузня Гнева за это заплатит.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он командует Экспедиционным корпусом из {link:kargath}Каргат{/link}а; его офицеры — {link:lexlort}Лекслорт{/link}, {link:galamav-the-marksman}Галамав{/link}, {link:shadowmage-vivian-lagrave}Вивиан Лагрейв{/link} и {link:hierophant-theodora-mulvadania}Теодора Мулвадания{/link}.
• Он вывешивает приказы убивать солдат Ярости {link:gorn}Горн{/link}а, которых ведет генерал Кузня Гнева, в {red:blackrock-depths}Глубинах Черной горы{/red}.
• Он готовит операцию, которая приведет к ответу Мясника Черной горы.
• Он приказывает убить хозяев {red:blackrock-spire}Вершины Черной горы{/red}.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ничего не написано о клане полководца и о его деяниях до Экспедиционного корпуса.]=],
		},
	},
	chapters = {
		{
			title = "Убивать на месте",
			hint = [=[Откликнитесь на объявления полководца против дворфов Черного Железа.]=],
			text = [=[Объявления появились на стенах {link:kargath}Каргат{/link}а от имени полководца. Бойцы, которых ведет Кузня Гнева, — безжалостные убийцы, повинные в резне 109-й. Каждого стражника, надзирателя и офицера Ярости {link:gorn}Горн{/link}а в Глубинах следовало уничтожить. Кровавый Клык обещал награды, а генералу обещал худшее.]=],
		},
		{
			title = "Смерть генералу Кузне Гнева",
			hint = [=[Завершите операцию полководца против генерала дворфов Черного Железа.]=],
			text = [=[Последней была операция, которой полководец ждал. Генерал Кузня Гнева, Мясник Черной горы, был убит в Глубинах. Кровавый Клык назвал это наконец свершившимся правосудием и вручил медальон Экспедиционного корпуса тому, кто ее исполнил.]=],
		},
		{
			title = "Приказ полководца",
			hint = "Исполните приказ полководца на Вершине Черной горы.",
			text = [=[Кровавый Клык приказал убить трех хозяев Вершины Черной горы и попросил принести любые бумаги, найденные среди их вещей. Бумаги ему принесли. Когда он прочел их, его зеленая кожа на миг побледнела. В них говорилось, что жив Ренд Чернорук — вождь, которого давно считали убитым. Кровавый Клык послал весть {link:orcs}орк{/link}у {link:eitrigg}Эйтриггу{/link} и вождю {link:thrall}Траллу{/link} в {link:orgrimmar}Оргриммар{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[«УБИВАТЬ НА МЕСТЕ: {link:dwarves}дворф{/link}ы Черного Железа»]=],
		},
		{ text = "«УБИВАТЬ НА МЕСТЕ: высокопоставленные чины Черного Железа»" },
		{ text = "«Операция: смерть генералу Кузне Гнева»" },
		{ text = "«Приказ полководца»" },
		{
			text = [=[«Мудрость {link:orcs}орк{/link}а {link:eitrigg}Эйтригг{/link}а»]=],
		},
	},
	bonds = {
		{ id = "lexlort", name = "Лекслорт", note = "начальник его разведки" },
		{ id = "galamav-the-marksman", name = "Галамав Стрелок", note = "один из его офицеров" },
		{ id = "eitrigg", name = "Эйтригг", note = "лучше всех знает клан Черной горы" },
